var MetroFareService = Class.create();

MetroFareService.prototype = {

    initialize: function() {
    },

    calculateFare: function(
        sourceId,
        destinationId,
        journeyType,
        passengerCount
    ) {

        passengerCount = parseInt(passengerCount, 10);

        // Validate source and destination
        if (!sourceId || !destinationId) {
            return {
                success: false,
                message: 'Source and destination are required.'
            };
        }

        // Source and destination cannot be same
        if (sourceId == destinationId) {
            return {
                success: false,
                message: 'Source and destination cannot be the same.'
            };
        }

        // Validate passenger count
        if (!passengerCount || passengerCount < 1) {
            return {
                success: false,
                message: 'Passenger count must be at least 1.'
            };
        }

        if (passengerCount > 6) {
            return {
                success: false,
                message: 'Maximum 6 passengers are allowed.'
            };
        }

        // Validate journey type
        if (
            journeyType != 'single' &&
            journeyType != 'return'
        ) {
            return {
                success: false,
                message: 'Invalid journey type.'
            };
        }

        // Find route
        var route = this._findRoute(
            sourceId,
            destinationId
        );

        if (!route) {
            return {
                success: false,
                message: 'Route data is not configured for the selected stations.'
            };
        }

        // Find fare based on route distance
        var baseFare = this._findFare(
            route.distance
        );

        if (baseFare === null) {
            return {
                success: false,
                message: 'No fare rule was found for this route distance.'
            };
        }

        // Single Journey = 1 trip
        // Return Journey = 2 trips
        var journeyCount = 1;

        if (journeyType == 'return') {
            journeyCount = 2;
        }

        // Calculate total fare
        var totalFare =
            baseFare *
            journeyCount *
            passengerCount;

        totalFare =
            Math.round(totalFare * 100) / 100;

        return {
            success: true,
            distance: route.distance,
            duration: route.duration,
            baseFare: baseFare,
            journeyType: journeyType,
            passengerCount: passengerCount,
            totalFare: totalFare
        };
    },


    // ========================================
    // Find route in direct or reverse direction
    // ========================================

    _findRoute: function(
        sourceId,
        destinationId
    ) {

        // Direct direction
        var route = this._queryRoute(
            sourceId,
            destinationId
        );

        if (route) {
            return route;
        }

        // Reverse direction
        return this._queryRoute(
            destinationId,
            sourceId
        );
    },


    // ========================================
    // Query Metro Route Master
    // ========================================

    _queryRoute: function(
        sourceId,
        destinationId
    ) {

        var route = new GlideRecord(
            'x_1958892_metro_0_metro_route_master'
        );

        route.addQuery(
            'source_station',
            sourceId
        );

        route.addQuery(
            'destination_station',
            destinationId
        );

        route.addQuery(
            'active',
            true
        );

        route.setLimit(1);

        route.query();

        if (route.next()) {

            return {
                distance: parseFloat(
                    route.getValue(
                        'distance_km'
                    )
                ),

                duration: parseInt(
                    route.getValue(
                        'duration_minutes'
                    ),
                    10
                )
            };
        }

        return null;
    },


    // ========================================
    // Find fare based on distance
    // ========================================

    _findFare: function(distance) {

        var fare = new GlideRecord(
            'x_1958892_metro_0_metro_fare_rule'
        );

        // Only active fare rules
        fare.addQuery(
            'active',
            true
        );

        // Minimum distance must be <= route distance
        fare.addQuery(
            'minimum_distance',
            '<=',
            distance
        );

        // Maximum distance must be >= route distance
        fare.addQuery(
            'maximum_distance',
            '>=',
            distance
        );

        // Only use currently effective fare rules
        var today = new GlideDate().getValue();

        fare.addQuery(
            'effective_from',
            '<=',
            today
        );

        // Latest applicable rule first
        fare.orderByDesc(
            'effective_from'
        );

        fare.setLimit(1);

        fare.query();

        if (fare.next()) {

            return parseFloat(
                fare.getValue(
                    'fare'
                )
            );
        }

        return null;
    },


    type: 'MetroFareService'
};
